package es.riegocerca.maps;
import android.content.Context;import android.net.Uri;import org.json.*;import org.xml.sax.*;import org.xml.sax.helpers.DefaultHandler;import javax.xml.parsers.SAXParserFactory;import java.io.*;import java.text.Normalizer;import java.util.*;import java.util.zip.*;
public final class XlsxStreamingImporter{private final Context c;public XlsxStreamingImporter(Context c){this.c=c;}public JSONArray read(Uri uri)throws Exception{File f=File.createTempFile("crnl_",".xlsx",c.getCacheDir()),sheet=File.createTempFile("crnl_sheet_",".xml",c.getCacheDir());try{try(InputStream in=c.getContentResolver().openInputStream(uri);OutputStream out=new FileOutputStream(f)){byte[] b=new byte[32768];int n;while((n=in.read(b))!=-1)out.write(b,0,n);}List<String> shared=new ArrayList<>();boolean got=false;try(ZipInputStream z=new ZipInputStream(new BufferedInputStream(new FileInputStream(f)))){ZipEntry e;while((e=z.getNextEntry())!=null){String n=e.getName();if("xl/sharedStrings.xml".equals(n)){ByteArrayOutputStream so=new ByteArrayOutputStream();byte[] sb=new byte[32768];int sk;while((sk=z.read(sb))!=-1)so.write(sb,0,sk);shared=parseShared(new ByteArrayInputStream(so.toByteArray()));}else if("xl/worksheets/sheet1.xml".equals(n)){try(OutputStream out=new BufferedOutputStream(new FileOutputStream(sheet))){byte[] b=new byte[32768];int k;while((k=z.read(b))!=-1)out.write(b,0,k);}got=true;}}}if(!got)throw new Exception("No se encontro la primera hoja del XLSX");return parseSheet(sheet,shared);}finally{f.delete();sheet.delete();}}
private List<String> parseShared(InputStream in)throws Exception{List<String> out=new ArrayList<>();SAXParserFactory.newInstance().newSAXParser().parse(in,new DefaultHandler(){boolean si=false,t=false;StringBuilder cell=new StringBuilder(),txt=new StringBuilder();public void startElement(String u,String l,String q,Attributes a){if(q.equals("si")){si=true;cell.setLength(0);}else if(si&&q.equals("t")){t=true;txt.setLength(0);}}public void characters(char[]c,int s,int n){if(t)txt.append(c,s,n);}public void endElement(String u,String l,String q){if(q.equals("t")&&t){cell.append(txt);t=false;}else if(q.equals("si")&&si){out.add(cell.toString());si=false;}}});return out;}
private JSONArray parseSheet(File xml,List<String> shared)throws Exception{JSONArray out=new JSONArray();SAXParserFactory.newInstance().newSAXParser().parse(xml,new DefaultHandler(){Map<Integer,String> row=new HashMap<>();String type="",ref="";StringBuilder val=new StringBuilder();boolean v=false,t=false;String[] headers=null;public void startElement(String u,String l,String q,Attributes a){if(q.equals("row"))row.clear();else if(q.equals("c")){type=a.getValue("t");ref=a.getValue("r");val.setLength(0);}else if(q.equals("v")){v=true;val.setLength(0);}else if(q.equals("t")&&"inlineStr".equals(type)){t=true;val.setLength(0);}}public void characters(char[]c,int s,int n){if(v||t)val.append(c,s,n);}public void endElement(String u,String l,String q){try{if(q.equals("v"))v=false;else if(q.equals("t")&&t)t=false;else if(q.equals("c")){String x=val.toString();if("s".equals(type)&&!x.isEmpty()){int i=Integer.parseInt(x);x=i>=0&&i<shared.size()?shared.get(i):"";}row.put(col(ref),x);}else if(q.equals("row")){if(headers==null){int max=row.keySet().stream().mapToInt(Integer::intValue).max().orElse(-1);headers=new String[max+1];for(int i=0;i<=max;i++)headers[i]=norm(row.getOrDefault(i,""));}else{String tipo="",nombre="",xs="",ys="";for(Map.Entry<Integer,String> e:row.entrySet()){int i=e.getKey();if(i<0||i>=headers.length)continue;String k=headers[i],x=e.getValue()==null?"":e.getValue().trim();if(k.equals("TIPO"))tipo=x;else if(k.equals("NOMBRE"))nombre=x;else if(k.equals("X")||k.equals("COORDENADAX"))xs=x;else if(k.equals("Y")||k.equals("COORDENADAY"))ys=x;}if(!nombre.isEmpty()&&!xs.isEmpty()&&!ys.isEmpty()){double x=num(xs),y=num(ys);if(Double.isFinite(x)&&Double.isFinite(y))out.put(new JSONObject().put("type",tipo).put("name",nombre).put("x",x).put("y",y));}}}}catch(Exception ex){throw new RuntimeException(ex);}}});if(out.length()==0)throw new Exception("No hay filas validas con NOMBRE, X e Y");return out;}
private static String norm(String s){return Normalizer.normalize(s==null?"":s,Normalizer.Form.NFD).replaceAll("\\p{M}","").replaceAll("[^A-Za-z0-9]","").toUpperCase(Locale.ROOT);}private static double num(String s){String x=s.trim().replace(" ","");if(x.indexOf(',')>=0&&x.indexOf('.')<0)x=x.replace(',','.');try{return Double.parseDouble(x);}catch(Exception e){return Double.NaN;}}private static int col(String r){int n=0;if(r==null)return -1;for(int i=0;i<r.length()&&Character.isLetter(r.charAt(i));i++)n=n*26+(Character.toUpperCase(r.charAt(i))-'A'+1);return n-1;}}
